73	///  .--()°'.'
74	/// '|, . ,'
75	///  !_-(_\
76	/// "#.trim_matches('\n'));
77	/// # Ok::<(), nu_test_support::tester::TestError>(())
78	/// ```
79	///
80	/// ```rust
