}", "newString": "", "originalFile": "//! A minimal abstraction for membership checks across container-like types.
//!
//! The [`Container`] trait unifies the various `contains`-style methods found on
//! standard library types (strings, slices, sets, maps, ranges, …) behind a
//! single interface. This is primarily useful for writing generic helpers such
//! as assertions that need to check membership without caring about the concrete
//! container type.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet, LinkedList, VecDeque};
use std::hash::{BuildHasher, Hash};
use std::ops::{Range, RangeFrom, RangeInclusive, RangeTo, RangeToInclusive};

/// A type that can be queried for membership of an [`Item`](Container::Item).
///
/// This provides a uniform [`contains`](Container::contains) method across a
/// wide range of standard library container types. For maps, membership is
/// checked by key.
pub trait Container {
    /// The type of element this container is queried against.
    ///
    /// This may be unsized (for example, [`str`] as the item type of [`String`]).
    type Item: ?Sized;

    /// Returns `true` if the container contains the given item.
    ///
    /// For map types, this checks whether the item is present as a key.
    fn contains(&self, item: &Self::Item) -> bool;
}

impl Container for str {
    type Item = str;

    fn contains(&self, item: &Self::Item) -> bool {
        // Inherent `str::contains` takes a `Pattern`; `&str` is one.
        str::contains(self, item)
    }
}

impl Container for String {
    type Item = str;

    fn contains(&self, item: &Self::Item) -> bool {
        str::contains(self.as_str(), item)
    }
}

impl<T: PartialEq, const N: usize> Container for [T; N] {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        <[T]>::contains(self.as_slice(), item)
    }
}

impl<T: PartialEq> Container for [T] {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        <[T]>::contains(self, item)
    }
}

impl<T: PartialEq> Container for Vec<T> {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        <[T]>::contains(self.as_slice(), item)
    }
}

impl<T: PartialEq> Container for VecDeque<T> {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        VecDeque::contains(self, item)
    }
}

impl<T: PartialEq> Container for LinkedList<T> {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        LinkedList::contains(self, item)
    }
}

impl<T, S> Container for HashSet<T, S>
where
    T: Eq + Hash,
    S: BuildHasher,
{
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        HashSet::contains(self, item)
    }
}

impl<T: Ord> Container for BTreeSet<T> {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        BTreeSet::contains(self, item)
    }
}

impl<K, V, S> Container for HashMap<K, V, S>
where
    K: Eq + Hash,
    S: BuildHasher,
{
    type Item = K;

    fn contains(&self, item: &Self::Item) -> bool {
        HashMap::contains_key(self, item)
    }
}

impl<K: Ord, V> Container for BTreeMap<K, V> {
    type Item = K;

    fn contains(&self, item: &Self::Item) -> bool {
        BTreeMap::contains_key(self, item)
    }
}

impl<T: PartialOrd> Container for Range<T> {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        Range::contains(self, item)
    }
}

impl<T: PartialOrd> Container for RangeInclusive<T> {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        RangeInclusive::contains(self, item)
    }
}

impl<T: PartialOrd> Container for RangeFrom<T> {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        RangeFrom::contains(self, item)
    }
}

impl<T: PartialOrd> Container for RangeTo<T> {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        RangeTo::contains(self, item)
    }
}

impl<T: PartialOrd> Container for RangeToInclusive<T> {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        RangeToInclusive::contains(self, item)
    }
}

impl<C> Container for &C
where
    C: Container + ?Sized,
{
    type Item = C::Item;

    fn contains(&self, item: &Self::Item) -> bool {
        (**self).contains(item)
    }
}

