/// Asserts that `haystack` contains `needle`.
///
/// Works with any type implementing [`Container`], including string slices,
/// owned [`String`]s, slices, [`Vec`], and other standard collection types.
/// The `needle` may be anything that borrows as the haystack's item type, so
/// (for example) both `&str` and `String` needles work against a `String`
/// haystack.
///
/// # Panics
///
/// Panics with a message showing both the haystack and the needle if the
/// haystack does not contain the needle.
pub fn assert_contains<H, N>(needle: N, haystack: H)
where
    H: Container + Debug,
    N: Borrow<H::Item>,
    H::Item: Debug,
{
    let needle = needle.borrow();
    assert!(
        haystack.contains(needle),
        "haystack does not contain needle\n  haystack: {haystack:?}\n    needle: {needle:?}",
    );
}

